export function findById(id: string) {
  return LARGE_DATASET.find(item => item.id === id);
}

export function filterByCategory(category: string) {
  return LARGE_DATASET.filter(item => item.category === category);
}

export function getTotalValue() {
  return LARGE_DATASET.reduce((sum, item) => sum + item.price * item.quantity, 0);
}
